#!/usr/bin/env python3
"""Generate layout.txt (field offsets/sizes) from include/FlightData.h.

Run after updating FlightData.h, then run `go test ./bms` to see which Go
fields need to be adjusted:

    python3 bms/testdata/gen_layout.py

Needs g++. The header is compiled natively (x86_64 Linux) with `long` redefined
to `int`, because `long` is 4 bytes on Windows but 8 bytes on Linux. All other
types and the alignment rules are the same as with MSVC on Windows x64.
"""
import os
import re
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
HEADER = os.path.normpath(os.path.join(HERE, "..", "..", "include", "FlightData.h"))
OUT = os.path.join(HERE, "layout.txt")

# Structs that are mapped 1:1 from shared memory.
STRUCTS = ["FlightData", "FlightData2", "OsbLabel", "OSBData"]

MEMBER = re.compile(r"^\s*([A-Za-z_][\w\s:]*?)\s+([A-Za-z_]\w*(?:\s*\[[^\]]+\])*(?:\s*,\s*[A-Za-z_]\w*(?:\s*\[[^\]]+\])*)*)\s*;")


def strip_comments(src):
    src = re.sub(r"/\*.*?\*/", "", src, flags=re.S)
    return re.sub(r"//[^\n]*", "", src)


def struct_body(src, name):
    m = re.search(r"(?:class|struct)\s+%s\s*\{" % name, src) or \
        re.search(r"typedef\s+struct\s*\{(?=[^{}]*\}\s*%s\s*;)" % name, src)
    if not m:
        sys.exit("struct %s not found" % name)
    depth, i = 1, m.end()
    start = i
    while depth:
        depth += {"{": 1, "}": -1}.get(src[i], 0)
        i += 1
    return src[start:i - 1]


def members(body):
    """Data members at the top level of a class body (skips enums and methods)."""
    top, depth, stmt = [], 0, ""
    for ch in body:
        if ch == "{":
            depth += 1
            stmt = ""  # drop enum/method headers
        elif ch == "}":
            depth -= 1
            stmt = ""
        elif depth == 0:
            stmt += ch
            if ch == ";":
                top.append(stmt.strip())
                stmt = ""
    names = []
    for s in top:
        s = re.sub(r"^public:\s*", "", s)
        if "(" in s:
            continue
        m = MEMBER.match(s)
        if not m:
            continue
        for decl in m.group(2).split(","):
            names.append(re.match(r"\s*(\w+)", decl).group(1))
    return names


def main():
    src = strip_comments(open(HEADER, encoding="utf-8", errors="replace").read())
    lines = ["#include <cstddef>", "#include <cstdio>", "#include <cstring>",
             "#include <vector>", "#include <memory>", "#include <string>",
             "#define long int  // Windows: long is 4 bytes",
             '#include "%s"' % HEADER, "int main() {"]
    for s in STRUCTS:
        lines.append('printf("%s size %%zu\\n", sizeof(%s));' % (s, s))
        for f in members(struct_body(src, s)):
            lines.append('printf("%s %s %%zu %%zu\\n", offsetof(%s, %s), sizeof(((%s*)0)->%s));'
                         % (s, f, s, f, s, f))
    lines.append("return 0; }")

    with tempfile.TemporaryDirectory() as tmp:
        cpp, exe = os.path.join(tmp, "layout.cpp"), os.path.join(tmp, "layout")
        open(cpp, "w").write("\n".join(lines))
        subprocess.run(["g++", "-std=c++17", "-w", "-o", exe, cpp], check=True)
        out = subprocess.run([exe], check=True, capture_output=True, text=True).stdout

    with open(OUT, "w") as f:
        f.write("# generated by gen_layout.py from include/FlightData.h - do not edit\n")
        f.write("# <struct> <field> <offset> <size> | <struct> size <size>\n")
        f.write(out)
    print("wrote", OUT)


if __name__ == "__main__":
    main()
